<?php declare(strict_types=1); require_once __DIR__.'/bootstrap.php';
try{verify_csrf($_POST['csrf']??null);$v=new App\FileValidator();$v->validate($_FILES['file_a']??[]);$v->validate($_FILES['file_b']??[]);$a=preg_replace('/[^A-Za-z0-9._-]/','_',basename($_FILES['file_a']['name']));$b=preg_replace('/[^A-Za-z0-9._-]/','_',basename($_FILES['file_b']['name']));$pa=UPLOAD_DIR.'/'.bin2hex(random_bytes(8)).'_'.$a;$pb=UPLOAD_DIR.'/'.bin2hex(random_bytes(8)).'_'.$b;if(!move_uploaded_file($_FILES['file_a']['tmp_name'],$pa)||!move_uploaded_file($_FILES['file_b']['tmp_name'],$pb))throw new RuntimeException('Unable to save uploaded files.');$r=new App\ExcelReader();$ha=$r->headers($pa);$hb=$r->headers($pb);if(!$ha||!$hb)throw new RuntimeException('Could not detect headers. Make sure row 1 contains column names.');$_SESSION['wizard']=['file_a'=>$pa,'file_b'=>$pb,'name_a'=>$_FILES['file_a']['name'],'name_b'=>$_FILES['file_b']['name'],'headers_a'=>$ha,'headers_b'=>$hb,'mode'=>$_POST['mode']??'smart'];redirect('mapping.php');}catch(Throwable $e){(new App\Logger())->error($e->getMessage(),['trace'=>$e->getTraceAsString()]);$_SESSION['error']=$e->getMessage();redirect('index.php');}
